import { DomainEventPublisher } from '../domain/events/DomainEventPublisher';
import { SubscriptionCanceledEvent } from '../domain/events/SubscriptionCanceledEvent';
import { Result } from '../domain/types/Result';

describe('CancelSubscriptionUseCase', () => {
  it('should cancel a subscription and publish cancellation event when subscription exists and is active', async () => {
    // Arrange
    const mockSubscriptionId = new SubscriptionId('sub-123');
    const mockUserId = new UserId('user-456');
    const mockSubscription = new Subscription(
      mockSubscriptionId,
      mockUserId,
      SubscriptionStatus.ACTIVE,
      new Date('2023-01-01'),
      new Date('2023-12-31')
    );

    const mockRepository = {
      findById: vi.fn(),
      save: vi.fn()
    } as unknown as SubscriptionRepository;

    const mockEventPublisher = {
      publish: vi.fn()
    } as unknown as DomainEventPublisher;

    const useCase = new CancelSubscriptionUseCase(mockRepository, mockEventPublisher);

    mockRepository.findById.mockResolvedValueOnce(Result.success(mockSubscription));
    mockRepository.save.mockResolvedValueOnce(Result.success(undefined));

    // Act
    const result = await useCase.execute({
      subscriptionId: mockSubscriptionId.value
    });

    // Assert
    expect(result.isSuccess).toBe(true);
    expect(mockRepository.findById).toHaveBeenCalledWith(mockSubscriptionId);
    expect(mockRepository.save).toHaveBeenCalledWith(mockSubscription);
    expect(mockEventPublisher.publish).toHaveBeenCalledWith(
      new SubscriptionCanceledEvent(
        mockSubscriptionId,
        mockUserId,
        new Date()
      )
    );
  });

  it('should return subscription not found error when subscription does not exist', async () => {
    // Arrange
    const mockSubscriptionId = new SubscriptionId('sub-123');
    const mockRepository = {
      findById: vi.fn(),
      save: vi.fn()
    } as unknown as SubscriptionRepository;

    const mockEventPublisher = {
      publish: vi.fn()
    } as unknown as DomainEventPublisher;

    const useCase = new CancelSubscriptionUseCase(mockRepository, mockEventPublisher);

    mockRepository.findById.mockResolvedValueOnce(Result.failure('Subscription not found'));

    // Act
    const result = await useCase.execute({
      subscriptionId: mockSubscriptionId.value
    });

    // Assert
    expect(result.isSuccess).toBe(false);
    expect(result.error).toBe('Subscription not found');
    expect(mockRepository.findById).toHaveBeenCalledWith(mockSubscriptionId);
    expect(mockRepository.save).not.toHaveBeenCalled();
    expect(mockEventPublisher.publish).not.toHaveBeenCalled();
  });

  it('should return already canceled error when subscription is already canceled', async () => {
    // Arrange
    const mockSubscriptionId = new SubscriptionId('sub-123');
    const mockUserId = new UserId('user-456');
    const mockSubscription = new Subscription(
      mockSubscriptionId,
      mockUserId,
      SubscriptionStatus.CANCELED,
      new Date('2023-01-01'),
      new Date('2023-12-31')
    );

    const mockRepository = {
      findById: vi.fn(),
      save: vi.fn()
    } as unknown as SubscriptionRepository;

    const mockEventPublisher = {
      publish: vi.fn()
    } as unknown as DomainEventPublisher;

    const useCase = new CancelSubscriptionUseCase(mockRepository, mockEventPublisher);

    mockRepository.findById.mockResolvedValueOnce(Result.success(mockSubscription));

    // Act
    const result = await useCase.execute({
      subscriptionId: mockSubscriptionId.value
    });

    // Assert
