import { Result, ok, error } from '../Result';
import { Subscription } from '../Entities/Subscription';
import { SubscriptionCannotBeCancelledError } from '../Errors/SubscriptionErrors';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionCannotBeCancelledError | SubscriptionNotFoundError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionCannotBeCancelledError | SubscriptionNotFoundError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return error(new SubscriptionNotFoundError());
      }

      if (!subscription.canBeCancelled()) {
        return error(new SubscriptionCannotBeCancelledError());
      }

      const cancelledSubscription = subscription.cancel();
      await this.subscriptionRepository.save(cancelledSubscription);

      return ok(cancelledSubscription);
    } catch (err) {
      if (err instanceof SubscriptionCannotBeCancelledError) {
        return error(err);
      }
      throw err;
    }
  }
}

