import { Result, ok, error } from '../Result';
import { ValidationError } from '../Errors/ValidationError';

export class Email {
  private constructor(public readonly value: string) {}

  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty or null
    if (!email || typeof email !== 'string') {
      return error(new ValidationError('Email must be a non-empty string'));
    }

    // Check if email is non-empty after trimming
    const trimmedEmail = email.trim();
    if (trimmedEmail.length === 0) {
      return error(new ValidationError('Email cannot be empty'));
    }

    // Normalize to lowercase
    const normalizedEmail = trimmedEmail.toLowerCase();

    // Validate email format using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return error(new ValidationError('Email format is invalid'));
    }

    return ok(new Email(normalizedEmail));
  }

  equals(other: Email): boolean {
    return this.value === other.value;
  }

  toString(): string {
    return this.value;
  }
}

// Domain/Result.ts
export type Result<T, E> = Success<T> | Failure<E>;

interface Success<T> {
  readonly isSuccess: true;
  readonly value: T;
  readonly error?: never;
}

interface Failure<E> {
  readonly isSuccess: false;
  readonly value?: never;
  readonly error: E;
}

export function ok<T>(value: T): Result<T, never> {
  return { isSuccess: true, value };
}

export function error<E>(error: E): Result<never, E> {
  return { isSuccess: false, error };
}
