// Domain/Entities/Subscription.ts
export interface Subscription {
  readonly id: string;
  readonly userId: string;
  readonly status: 'active' | 'cancelled' | 'expired';
  readonly startDate: Date;
  readonly endDate: Date;
  readonly plan: string;
}

export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly userId: string,
    public readonly status: 'active' | 'cancelled' | 'expired',
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    userId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  isActive(): boolean {
    return this.status === 'active';
  }

  isExpired(): boolean {
    return this.status === 'expired';
  }

  isCancelled(): boolean {
    return this.status === 'cancelled';
  }

  cancel(): Subscription {
    if (this.isExpired()) {
      throw new SubscriptionAlreadyExpiredError();
    }

    return new Subscription(
      this.id,
      this.userId,
      'cancelled',
      this.startDate,
      this.endDate,
      this.plan
    );
  }
}

// Domain/Errors/SubscriptionErrors.ts
export class SubscriptionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SubscriptionError';
  }
}

export class SubscriptionAlreadyExpiredError extends SubscriptionError {
  constructor() {
    super('Cannot cancel an already expired subscription');
    this.name = 'SubscriptionAlreadyExpiredError';
  }
}

export class SubscriptionNotFoundError extends SubscriptionError {
  constructor() {
    super('Subscription not found');
    this.name = 'SubscriptionNotFoundError';
  }
}

// Domain/UseCases/CancelSubscriptionUseCase.ts
import { Result, ok, error } from '../Result';
import { Subscription } from '../Entities/Subscription';
import { SubscriptionError } from '../Errors/SubscriptionErrors';

export interface CancelSubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(private readonly repository: CancelSubscriptionRepository) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionError>> {
    try {
      const subscription = await this.repository.findById(subscriptionId);

      if (!subscription) {
        return error(new SubscriptionNotFoundError());
      }

      const cancelledSubscription = subscription.cancel();
      await this.repository.save(cancelledSubscription);

      return ok(cancelledSubscription);
    } catch (err) {
      if (err instanceof SubscriptionError) {
        return error(err);
      }
      throw err;
    }
  }
}

// Domain/Result.ts
export type Result<T, E extends Error> = {
  isSuccess: boolean;
  isError: boolean;
  value?: T;
  error?: E;
};

export function ok<T, E extends Error>(value: T): Result<T, E> {
  return {
    isSuccess: true,
    isError: false,
    value,
  };
}

export function error<T, E extends Error>(error: E): Result<T, E> {
  return {
    isSuccess: false,
    isError: true,
    error,
  };
}
