// Domain/Errors/ValidationError.ts
export class ValidationError {
  constructor(public readonly message: string) {}
}

// Domain/ValueObjects/Email.ts
import { Result, Ok, Err } from '../Result';
import { ValidationError } from '../Errors/ValidationError';

export class Email {
  private constructor(public readonly value: string) {}

  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty or null
    if (!email || typeof email !== 'string') {
      return Err(new ValidationError('Email must be a non-empty string'));
    }

    // Check if email is not empty after trimming
    const trimmedEmail = email.trim();
    if (trimmedEmail.length === 0) {
      return Err(new ValidationError('Email cannot be empty'));
    }

    // Normalize to lowercase
    const normalizedEmail = trimmedEmail.toLowerCase();

    // Validate email format using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return Err(new ValidationError('Email format is invalid'));
    }

    // Create and return the Email value object
    return Ok(new Email(normalizedEmail));
  }

  equals(other: Email): boolean {
    return this.value === other.value;
  }

  toString(): string {
    return this.value;
  }
}

// Domain/Result.ts
export type Result<T, E> = Ok<T> | Err<E>;

export class Ok<T> {
  constructor(public readonly value: T) {}
}

export class Err<E> {
  constructor(public readonly error: E) {}
}

export function Ok<T>(value: T): Result<T, never> {
  return new Ok(value);
}

export function Err<E>(error: E): Result<never, E> {
  return new Err(error);
}
```

This implementation provides:

1. A pure Value Object `Email` that encapsulates email validation logic
2. Invariant validation:
   - Checks for non-empty strings
   - Validates email format using regex
   - Normalizes email to lowercase
3. Returns a `Result<Email, ValidationError>` to handle validation failures gracefully
4. Follows Clean Architecture principles with no dependencies on external libraries
5. Uses the Result pattern for error handling
6. Implements proper equality checking and string conversion
7. Enforces the Dependency Rule by keeping all domain logic self-contained

The `Email` value object ensures that:
- All emails are normalized to lowercase
- Empty or invalid emails are rejected
- The value object is immutable
- Validation is performed at creation time
- The domain layer doesn't depend on any infrastructure or external libraries

