import { Result, Ok, Err } from "../../Shared/Result";
import { Subscription } from "../Entities/Subscription";
import { InvalidSubscriptionError } from "../Errors/SubscriptionErrors";

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, InvalidSubscriptionError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, InvalidSubscriptionError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return Err(new InvalidSubscriptionError("Subscription not found"));
      }

      if (!subscription.canCancel()) {
        return Err(new InvalidSubscriptionError("Cannot cancel expired or inactive subscription"));
      }

      const cancelledSubscription = subscription.cancel();
      await this.subscriptionRepository.save(cancelledSubscription);

      return Ok(cancelledSubscription);
    } catch (error) {
      if (error instanceof InvalidSubscriptionError) {
        return Err(error);
      }
      return Err(new InvalidSubscriptionError("Failed to cancel subscription"));
    }
  }
}

